#include "packet_protocol.hpp"
#include <functional>
#include <iostream>
using namespace packet_protocol;
static void check(bool value,const char* s){if(!value)throw std::runtime_error(s);}
static void reject(const std::function<void()>& fn){bool failed=false;try{fn();}catch(const std::runtime_error&){failed=true;}check(failed,"negative operation accepted");}
static Protocol make(){return Protocol({{1,7,60,{0},{{8320,112}}},{2,11,65,{1},{{8592,128}}},{3,19,1514,{2,3},{{9024,528},{12048,1040}}}},4);}
static Receipt issue(Protocol& p,unsigned s,unsigned e,uint64_t id){unsigned pid=s<2?s+1:3;const auto& x=p.packet(pid);p.reserve(s,e,pid,x.generation,x.spec.cookie);return p.accept_next(e,id);}
static Token deliver(Protocol& p,unsigned pid){auto t=p.acquire(pid,p.packet(pid).generation);p.allow_read(pid,&t,false,p.packet(pid).spec.destination_line_closure[0].offset,1);p.validated(pid,&t);p.publish(pid,&t);p.source_reused(pid);p.allow_read(pid,&t,true,p.packet(pid).spec.destination_line_closure[0].offset,1);p.consumer_done(pid,&t);p.return_B(pid);return t;}
static void finish(Protocol& p,uint64_t first=2){for(unsigned s=0;s<4;++s){if(p.complete(issue(p,s,0,first+s)))deliver(p,s<2?s+1:3);}}
int main(){unsigned count=0;std::cout<<"{\"scope\":\"protocol unit simulated faults; not production AXI recovery\",\"tests\":[";
 auto test=[&](const char* name,const std::function<void()>& fn){fn();if(count++)std::cout<<",";std::cout<<"{\"name\":\""<<name<<"\",\"pass\":true}";};
 try{
  test("partial_packet3_cannot_acquire_publish_or_reuse",[]{auto p=make();p.complete(issue(p,2,1,2));check(p.packet(3).state==State::dma_owned,"partial state");reject([&]{p.acquire(3,1);});reject([&]{p.publish(3,nullptr);});reject([&]{p.source_reused(3);});check(!p.packet(3).source_retired,"partial retirement");});
  test("out_of_order_complete_prefix_is_held",[]{auto p=make();p.complete(issue(p,2,1,2));p.complete(issue(p,3,1,3));check(p.ready_prefix()==0,"out of order ready");auto t=p.acquire(3,1);p.validated(3,&t);reject([&]{p.publish(3,&t);});check(p.packet(3).state==State::acquired,"reject changed state");});
  test("missing_acquire_token_does_not_advance",[]{auto p=make();p.complete(issue(p,0,0,2));auto t=p.acquire(1,1);p.validated(1,&t);reject([&]{p.allow_read(1,nullptr,false,8331,72);});reject([&]{p.publish(1,nullptr);});reject([&]{p.consumer_done(1,nullptr);});check(p.packet(1).state==State::acquired,"missing token advanced");});
  test("stale_token_generation_cookie_nonce_rejected",[]{auto p=make();p.complete(issue(p,0,0,2));auto good=p.acquire(1,1);p.validated(1,&good);for(int k=0;k<4;++k){auto bad=good;if(k==0)++bad.generation;if(k==1)++bad.cookie;if(k==2)++bad.nonce;if(k==3)++bad.packet;reject([&]{p.publish(1,&bad);});check(p.packet(1).state==State::acquired,"bad token advanced");}});
  test("valid_token_cannot_read_peer_pool_or_overflow",[]{auto p=make();p.complete(issue(p,0,0,2));auto t=p.acquire(1,1);for(auto r:std::vector<Range>{{8605,77},{0,16384},{8331,UINT64_MAX},{UINT64_MAX,72},{8319,1},{8432,1},{8331,0}})reject([&]{p.allow_read(1,&t,false,r.offset,r.length);});p.allow_read(1,&t,false,8320,112);check(p.packet(1).state==State::acquired,"invalid range advances state");});
  test("malformed_packet_identity_or_closure_rejected",[]{reject([]{Protocol p({{0,7,60,{0},{{8320,112}}}},1);});reject([]{Protocol p({{1,7,60,{0},{{8320,112}}},{1,11,65,{1},{{8592,128}}}},2);});reject([]{Protocol p({{1,7,60,{0},{{8320,112}}},{2,7,65,{1},{{8592,128}}}},2);});reject([]{Protocol p({{1,7,60,{0},{{8320,112}}},{2,11,65,{1},{{8400,128}}}},2);});});
  test("unvalidated_done_does_not_certify_bytes",[]{auto p=make();p.complete(issue(p,0,0,2));auto t=p.acquire(1,1);reject([&]{p.publish(1,&t);});reject([&]{p.source_reused(1);});check(p.packet(1).state==State::acquired,"unvalidated publish advanced");});
  test("return_before_consumer_rejected",[]{auto p=make();p.complete(issue(p,0,0,2));auto t=p.acquire(1,1);p.validated(1,&t);p.publish(1,&t);reject([&]{p.return_B(1);});check(p.packet(1).state==State::prefix_published,"early return advanced");});
  test("duplicate_completion_quarantines",[]{auto p=make();auto r=issue(p,0,0,2);p.complete(r);reject([&]{p.complete(r);});check(p.quarantined()&&p.mapping_retained(),"duplicate not retained");});
  test("stale_generation_completion_quarantines",[]{auto p=make();auto r=issue(p,0,0,2);++r.generation;reject([&]{p.complete(r);});check(p.quarantined()&&!p.packet(1).source_retired,"stale completion accepted");});
  test("engine_local_id_collision_cannot_cross_join",[]{auto p=make();auto a=issue(p,0,0,2);auto b=issue(p,2,1,2);check(a.id==b.id,"unit collision absent");a.engine=1;reject([&]{p.complete(a);});check(p.quarantined()&&p.packet(1).state==State::dma_owned,"cross-engine join accepted");});
  test("wrong_span_packet_cookie_id_rejected",[]{for(int k=0;k<4;++k){auto p=make();auto r=issue(p,0,0,2);if(k==0)++r.span;if(k==1)++r.packet;if(k==2)++r.cookie;if(k==3)++r.id;reject([&]{p.complete(r);});check(p.quarantined(),"bad receipt did not quarantine");}});
  test("unknown_next_acceptance_retains_mapping",[]{for(uint64_t bad:{uint64_t(0),uint64_t(3)}){auto p=make();p.reserve(0,0,1,1,7);reject([&]{p.accept_next(0,bad);});check(p.quarantined()&&p.mapping_retained(),"unknown NEXT releases allocation");reject([&]{p.reserve(1,1,2,1,11);});}});
  test("timeout_freezes_all_operations_without_rolling_back_delivered",[]{auto p=make();p.complete(issue(p,0,0,2));auto old=deliver(p,1);auto r=issue(p,1,0,3);p.complete(r);auto t=p.acquire(2,1);p.validated(2,&t);p.timeout();reject([&]{p.reserve(2,1,3,1,19);});reject([&]{p.acquire(2,1);});reject([&]{p.publish(2,&t);});reject([&]{p.allow_read(2,&t,false,8605,77);});reject([&]{p.consumer_done(2,&t);});reject([&]{p.return_B(2);});reject([&]{p.source_reused(2);});reject([&]{p.teardown(true);});check(p.packet(1).state==State::B_returned&&p.packet(2).state==State::acquired&&p.mapping_retained(),"timeout changed prior state or freed");(void)old;});
  test("early_generation_reuse_and_unchecked_teardown_rejected",[]{auto p=make();reject([&]{p.reuse_generation();});reject([&]{p.teardown(true);});finish(p);reject([&]{p.teardown(false);});check(p.mapping_retained(),"unchecked release");});
  test("legal_generation_reuse_rejects_old_acquire_token",[]{auto p=make();p.complete(issue(p,0,0,2));auto old=deliver(p,1);for(unsigned s=1;s<4;++s)if(p.complete(issue(p,s,0,2+s)))deliver(p,s<2?s+1:3);p.reuse_generation();auto r=issue(p,0,0,6);check(r.generation==2,"generation not advanced");p.complete(r);auto fresh=p.acquire(1,2);p.validated(1,&fresh);reject([&]{p.publish(1,&old);});p.publish(1,&fresh);p.source_reused(1);p.consumer_done(1,&fresh);p.return_B(1);for(unsigned s=1;s<4;++s)if(p.complete(issue(p,s,0,6+s)))deliver(p,s<2?s+1:3);p.teardown(true);check(!p.mapping_retained(),"legal final release absent");});
  test("all_original_packets_can_complete_and_checked_teardown",[]{auto p=make();finish(p);p.teardown(true);check(!p.mapping_retained()&&!p.quarantined(),"normal teardown");});
  std::cout<<"],\"count\":"<<count<<",\"pass\":true}\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}
}
